To coordinate cooperative threads without busy-waiting (CPU spinning), Java provides wait(), notify(), and notifyAll() on java.lang.Object.
Producer-Consumer Model Example:
class Buffer {
    private int data;
    private boolean available = false;
    public synchronized void produce(int val) throws InterruptedException {
        while (available) wait(); // Wait if buffer is full
        data = val; available = true;
        System.out.println('Produced: ' + val);
        notifyAll(); // Wake up consumers
    }
    public synchronized int consume() throws InterruptedException {
        while (!available) wait(); // Wait if buffer is empty
        available = false;
        System.out.println('Consumed: ' + data);
        notifyAll(); // Wake up producers
        return data;
    }
}

• try: Declares a guarded region. Any exception thrown within this block terminates try execution and jumps to the matching catch.
• catch: Matches the thrown exception type. Java supports multi-catch blocks: catch(IOException | SQLException e).
• finally: Guarantees resource deallocation (closing file handles, database connections, socket streams).
• throw: Programmatically triggers an exception: if (age < 18) throw new InvalidAgeException('Not eligible');
• throws: Listed in method signatures: public void readFile() throws IOException, SQLException { ... }

class InvalidBalanceException extends Exception {
    public InvalidBalanceException(String msg) { super(msg); }
}
public class BankAccount {
    private double balance = 1000;
    public void withdraw(double amount) throws InvalidBalanceException {
        if (amount > balance) throw new InvalidBalanceException('Insufficient funds');
        balance -= amount;
    }
    public static void main(String[] args) {
        BankAccount acc = new BankAccount();
        try {
            acc.withdraw(1500);
        } catch (InvalidBalanceException e) {
            System.err.println('Caught Exception: ' + e.getMessage());
        } finally {
            System.out.println('Audit log updated; connection closed.');
        }
    }
}

List<String> list = new ArrayList<>();
list.add("Java"); list.add("Python");
ListIterator<String> lit = list.listIterator();
while (lit.hasNext()) {
    String val = lit.next();
    if (val.equals("Java")) lit.set("Core Java");
}
This demonstrates safe bidirectional element replacement using ListIterator.

import java.sql.*;
public class StudentQuery {
    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost:3306/college_db";
        String user = "root", pass = "secret";
        String sql = "SELECT id, name, marks FROM students WHERE marks >= ?";
        try (Connection con = DriverManager.getConnection(url, user, pass);
             PreparedStatement pstmt = con.prepareStatement(sql)) {
            pstmt.setDouble(1, 75.0);
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    System.out.println(rs.getInt("id") + " | " + rs.getString("name") + " | " + rs.getDouble("marks"));
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;

@WebServlet("/login")
public class LoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        response.setContentType("text/html;charset=UTF-8");
        String email = request.getParameter("email");
        String pass = request.getParameter("password");
        PrintWriter out = response.getWriter();
        if ("admin@college.edu".equals(email) && "secret123".equals(pass)) {
            // Valid: Forward to dashboard internally
            RequestDispatcher rd = request.getRequestDispatcher("dashboard.jsp");
            request.setAttribute("user", email);
            rd.forward(request, response);
        } else {
            // Invalid: Redirect back with error query parameter
            response.sendRedirect("login.html?error=invalid_credentials");
        }
    }
}

import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String user = req.getParameter("username");
        String pass = req.getParameter("password");
        if ("admin".equals(user) && "pass123".equals(pass)) {
            HttpSession session = req.getSession(true); // Create new session
            session.setAttribute("currentUser", user);
            res.sendRedirect("dashboard.jsp");
        } else {
            res.sendRedirect("login.html?error=invalid");
        }
    }
}
